CUDA_ARCH=70
CFLAGS ?= -O3 -g -ffast-math -mno-avx -mno-avx2 -mno-avx512f -fPIC -MMD -MP -DGIT_COMMIT_ID=\"$(GIT_TIP)\" -DGKYL_BUILD_DATE=\"$(BUILD_DATE_STR)\" -DGKYL_GIT_CHANGESET=\"$

# App to build
BUILD_APP=pkpm

# Library paths
LAPACK_INC_DIR=/home/maxwell-rosen/gkylsoft/OpenBLAS/include/
LAPACK_LIB_DIR=/home/maxwell-rosen/gkylsoft/OpenBLAS/lib/
LAPACK_LIB_NAME=openblas

SUPERLU_INC_DIR=/home/maxwell-rosen/gkylsoft/superlu/include/
SUPERLU_LIB_DIR=/home/maxwell-rosen/gkylsoft/superlu/lib/
SUPERLU_LIB_NAME=superlu

USE_MPI=1
CONF_MPI_INC_DIR=/home/maxwell-rosen/gkylsoft/openmpi/include
CONF_MPI_LIB_DIR=/home/maxwell-rosen/gkylsoft/openmpi/lib/

USE_NCCL=
CONF_NCCL_INC_DIR=/kPqbV,%S72JS/y
CONF_NCCL_LIB_DIR=

USE_CUDSS=
CONF_CUDSS_INC_DIR=/home/maxwell-rosen/gkylsoft/cuDSS/include/
CONF_CUDSS_LIB_DIR=/home/maxwell-rosen/gkylsoft/cuDSS/lib/

USE_LUA=1
CONF_LUA_INC_DIR=/home/maxwell-rosen/gkylsoft/luajit/include/luajit-2.1/
CONF_LUA_LIB_DIR=/home/maxwell-rosen/gkylsoft/luajit/lib/
CONF_LUA_LIB=luajit-5.1

CUDAMATH_LIB_DIR=

FIN_APP_LIB_DIR=-L../${BUILD_DIR}/pkpm
FIN_APP_LIB=-lg0pkpm

.PHONY:
all: pkpm pkpm-unit pkpm-regression ## Build only specified Apps (pkpm)

.PHONY: install
install: pkpm-install ## Install gkeyll executable
	cd gkeyll && ${MAKE} -f Makefile-gkeyll install

