// Context for Gaussian-weighted integration
struct gaussian_weight_ctx {
  struct gkyl_position_map *gpm;
  double theta_c; // Center point for Gaussian
  double wd2; // Half-width of averaging window
  double sigma; // Standard deviation for Gaussian weight
};

double position_map_constB_z_numeric_dbl_exp_wrapper(double z, void *ctx)
{
  struct gaussian_weight_ctx *gw_ctx = ctx;
  double fout[3];
  position_map_constB_z_numeric(0.0, &z, fout, gw_ctx->gpm);

  // Apply Gaussian weight: exp(-(z-theta_c)^2 / (2*sigma^2))
  double dz = z - gw_ctx->theta_c;
  double weight = exp(-dz * dz / (2.0 * gw_ctx->sigma * gw_ctx->sigma));

  return fout[0] * weight;
}

double gaussian_norm_wrapper(double z, void *ctx)
{
  struct gaussian_weight_ctx *gw_ctx = ctx;

  // Return just the Gaussian weight for normalization
  double dz = z - gw_ctx->theta_c;
  double weight = exp(-dz * dz / (2.0 * gw_ctx->sigma * gw_ctx->sigma));

  return weight;
}

/**
 * Maps the uniform computational coordinate to a non-uniform coordinate
 * according to the numeric constant B mapping.
 * 
 * @param t Time
 * @param xn Uniform coordinate
 * @param fout Non-uniform coordinate
 * @param ctx The context for the position map
 */
static void
position_map_constB_z_numeric_moving_average(double t, const double *xn, double *fout, void *ctx)
{
  struct gkyl_position_map *gpm = ctx;
  if (gpm->constB_ctx->gaussian_std == 0.0) {
    position_map_constB_z_numeric(t, xn, fout, ctx);
    return;
  }

  const double theta_c = xn[0];
  const double sigma = gpm->constB_ctx->gaussian_std;
  const double max_width = gpm->constB_ctx->gaussian_max_integration_width;
  const double tmin = gpm->constB_ctx->theta_min;
  const double tmax = gpm->constB_ctx->theta_max;

  // Shrink the half-width symmetrically to stay within bounds
  // This ensures the integration window is always centered at theta_c
  double dist_to_min = theta_c - tmin;
  double dist_to_max = tmax - theta_c;
  double wd2 = fmin(fmin(dist_to_min, dist_to_max) * 0.99, max_width / 2);

  // If the symmetric window is too small, fall back to unsmoothed
  if (wd2 < 1e-6) {
    position_map_constB_z_numeric(t, xn, fout, ctx);
static void asymmetric_bmag(double t, const double *xn, double *out, void *ctx)
{
  bool flat = *(bool *)ctx;
  out[0] = flat ? 2.0 : xn[0] < 0.25 ? 2.0 - xn[0] : 1.75 + 2.0 * (xn[0] - 0.25);
}

static void test_numeric_degenerate_and_strength(void)
{
  for (int flat = 0; flat < 2; ++flat) {
    struct gkyl_rect_grid grid, grid3;
    gkyl_rect_grid_init(&grid, 1, (double[]){-1}, (double[]){1}, (int[]){16});
    gkyl_rect_grid_init(&grid3, 3, (double[]){-2, -1, -1}, (double[]){-1, 1, 1}, (int[]){1, 1, 16});
    struct gkyl_range local, ext, global3, ext3;
    gkyl_create_grid_ranges(&grid, (int[]){1}, &ext, &local);
    gkyl_create_grid_ranges(&grid3, (int[]){1, 1, 1}, &ext3, &global3);
    struct gkyl_basis basis;
    gkyl_cart_modal_serendip(&basis, 1, 1);
    struct gkyl_position_map *pmap = gkyl_position_map_new(
      (struct gkyl_position_map_inp){.id = GKYL_PMAP_CONSTANT_DB_NUMERIC, .map_strength = 1.0},
      grid, local, ext, local, ext, basis
    );
    struct gkyl_array *bmag = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, ext.volume);
    bool uniform = flat;
    struct gkyl_proj_on_basis *proj =
      gkyl_proj_on_basis_new(&grid, &basis, 2, 1, asymmetric_bmag, &uniform);
    gkyl_proj_on_basis_advance(proj, 0.0, &local, bmag);
    gkyl_proj_on_basis_release(proj);
    gkyl_position_map_optimize(pmap, grid3, global3);
    gkyl_position_map_set_bmag(pmap, NULL, bmag);
    gkyl_position_map_optimize(pmap, grid3, global3);
    TEST_CHECK(gkyl_compare(pmap->constB_ctx->psi, -1.5, 1e-14));
    for (int strength = 0; strength < 3; ++strength) {
      pmap->constB_ctx->map_strength = 0.5 * strength;
      for (int point = 0; point <= 32; ++point) {
        // Include the exact computational location of the asymmetric minimum.
        double x = point == 16 ? -1.0 + 2.0 * 1.25 / 2.75 : -1.0 + point / 16.0;
        double full, actual;
        pmap->constB_ctx->map_strength = 1.0;
        pmap->maps[2](0, &x, &full, pmap->ctxs[2]);
        pmap->constB_ctx->map_strength = 0.5 * strength;
        pmap->maps[2](0, &x, &actual, pmap->ctxs[2]);
        double expected = uniform ? x : (1.0 - 0.5 * strength) * x + 0.5 * strength * full;
        TEST_CHECK(gkyl_compare(actual, expected, 2e-12));
        TEST_MSG(
          "flat %d strength %g x %g actual %g expected %g", flat, 0.5 * strength, x, actual,
          expected
        );
      }
    }
    if (!uniform) {
      pmap->constB_ctx->enable_maximum_slope_limits_at_min_B = true;
      pmap->constB_ctx->enable_maximum_slope_limits_at_max_B = true;
      pmap->constB_ctx->maximum_slope_at_min_B = 2.0;
      pmap->constB_ctx->maximum_slope_at_max_B = 2.0;
      double x_min = -1.0 + 2.0 * 1.25 / 2.75;
      for (int strength = 1; strength <= 2; ++strength) {
        pmap->constB_ctx->map_strength = strength * 0.5;
        double left = x_min - 1e-8, right = x_min + 1e-8, mapped_left, mapped_right;
        pmap->maps[2](0, &left, &mapped_left, pmap->ctxs[2]);
        pmap->maps[2](0, &right, &mapped_right, pmap->ctxs[2]);
        TEST_CHECK(mapped_right >= mapped_left);
        TEST_CHECK(mapped_right - mapped_left < 4e-8);
        double previous = -1.0;
        for (int i = 1; i <= 256; ++i) {
          double x = -1.0 + i / 128.0, mapped;
          pmap->maps[2](0, &x, &mapped, pmap->ctxs[2]);
          TEST_CHECK(mapped > previous);
          TEST_CHECK(mapped - previous <= 2.0 / 128.0 + 1e-12);
          previous = mapped;
        }
      }
    }
    // Replacing B must release the previous optimization storage.
    gkyl_position_map_set_bmag(pmap, NULL, bmag);
    gkyl_position_map_optimize(pmap, grid3, global3);
    gkyl_array_release(bmag);
    gkyl_position_map_release(pmap);
  }
}

